formulas.expression:
IF(
	AND(
	  MONTH({!Contract_Start_Date}) = 2,
	  DAY({!Contract_Start_Date}) = 29,
	  NOT( OR( 
		MOD(YEAR({!Contract_Start_Date}),400) = 0, AND( 
		    MOD(YEAR({!Contract_Start_Date}),4) = 0,
		    MOD(YEAR({!Contract_Start_Date}),100) <> 0
                    )
		)
	) 
	),
	DATE( YEAR({!Contract_Start_Date}) + {!monthToYearValue}, 3, 1) -1 ,
	DATE( YEAR({!Contract_Start_Date}) + {!monthToYearValue}, MONTH({!Contract_Start_Date}) , DAY({!Contract_Start_Date})) -1
)
